(function(){
 let user=null,profile=null,pendingAction=null;
 const db=()=>window.zwconnectSupabase||null;
 const el=id=>document.getElementById(id);
 const text=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
 function status(message,error=false){const host=el('customerAuthStatus');if(host){host.textContent=message||'';host.classList.toggle('error',error)}}
 function tab(name){document.querySelectorAll('[data-customer-auth-tab]').forEach(button=>{const active=button.dataset.customerAuthTab===name;button.setAttribute('aria-selected',String(active))});el('customerSignInForm')?.classList.toggle('hidden',name!=='signin');el('customerSignUpForm')?.classList.toggle('hidden',name!=='signup');status('')}
 function updateButtons(){const label=el('customerAccountLabel');if(label)label.textContent=user?(profile?.display_name||user.email?.split('@')[0]||'My account'):'Customer sign in';document.querySelector('#mobileCustomerAccount span')?.replaceChildren(document.createTextNode(user?'Orders':'Account'));window.ZWCart?.setCustomerIdentity(user?.id||null);window.ZWOffline?.setContext(user?'customer':'public',{userId:user?.id||null,email:user?.email||null,shopId:null,force:true})}
 function openAuth(reason){pendingAction=reason||null;const message=reason==='checkout'?'Your cart is saved. Sign in or create a free customer account to continue to payment.':reason;el('customerAuthTitle').textContent=reason?'Sign in to continue':'Customer account';el('customerAuthLead').textContent=message||'Browse freely, then sign in to place and manage orders.';tab('signin');openModal('customerAuthModal');setTimeout(()=>el('customerSignInForm')?.querySelector('input')?.focus(),80)}
 async function getProfile(){if(!user||!db())return null;let {data,error}=await db().from('customer_profiles').select('display_name,phone,status').eq('user_id',user.id).maybeSingle();if(error&&!/does not exist/i.test(error.message))throw error;if(!data&&user.user_metadata?.account_type==='customer'){const created=await db().rpc('register_customer_profile',{full_name:user.user_metadata.full_name||user.email?.split('@')[0]||'Customer',phone_number:user.user_metadata.phone||'',accepted_terms:true});if(created.error)throw created.error;({data,error}=await db().from('customer_profiles').select('display_name,phone,status').eq('user_id',user.id).maybeSingle());if(error)throw error}profile=data||null;return profile}
 async function refresh(){const client=db();if(!client){user=null;profile=null;updateButtons();return null}const {data}=await client.auth.getSession();user=data?.session?.user||null;if(user&&navigator.onLine){try{await getProfile()}catch(error){console.warn('Customer profile unavailable',error)}}else if(!user)profile=null;updateButtons();return user}
 async function requireAccount(reason='Create or sign in to your free customer account before placing an order.'){
  await refresh();if(!user){openAuth(reason);return null}
  if(!profile){status('This login is not a customer account. Business roles must use a separate customer account.',true);openAuth('This login belongs to a business role. Sign in with a separate customer account to order.');return null}
  if(profile.status!=='active'){openAuth('This customer account is suspended. Contact ZWConnect support.');status('Account suspended',true);return null}
  return user
 }
 function orderCard(order){const amount=Number(order.amount||0).toFixed(2),date=order.submitted_at?new Date(order.submitted_at).toLocaleString('en-ZW',{dateStyle:'medium',timeStyle:'short'}):'';return `<article class="customer-order-card"><div><span class="status-pill">${text(String(order.status||'pending').replaceAll('_',' '))}</span><h3>${text(order.shop||'ZWConnect shop')}</h3><small>${text(date)} • ${text((order.id||'').slice(0,8).toUpperCase())}</small></div><strong>US$ ${amount}</strong><p>${text(order.confirmation_note||order.rejection_reason||'The shop will update this order after reviewing payment.')}</p><button type="button" data-open-customer-order="${text(order.id)}" data-order-token="${text(order.tracking_token||'')}">View order</button></article>`}
 async function showOrders(){const account=await requireAccount('Sign in to view your private orders and delivery progress.');if(!account)return;openModal('customerOrdersModal');const host=el('customerOrdersList');host.innerHTML='<div class="customer-orders-loading">Loading your orders…</div>';if(!navigator.onLine){host.innerHTML='<div class="customer-orders-empty"><strong>You are offline</strong><p>Orders saved on this device remain available from the tracker. Cloud updates resume when you reconnect.</p></div>';return}const {data,error}=await db().rpc('get_my_customer_orders');if(error){host.innerHTML=`<div class="customer-orders-empty"><strong>Orders could not load</strong><p>${text(error.message)}</p></div>`;return}host.innerHTML=data?.length?data.map(orderCard).join(''):'<div class="customer-orders-empty"><strong>No orders yet</strong><p>Browse any shop and add available products to your cart.</p></div>';window.lucide?.createIcons()}
 async function signIn(form){const client=db();if(!client)return status('Supabase is not connected yet. Add the production Supabase client before accepting customer accounts.',true);const data=Object.fromEntries(new FormData(form));status('Signing in…');const {data:result,error}=await client.auth.signInWithPassword({email:data.email.trim(),password:data.password});if(error)return status(error.message,true);user=result.user;try{await getProfile()}catch(error){return status(error.message,true)}if(!profile){await client.auth.signOut();user=null;updateButtons();return status('This email is assigned to a business role, not a customer account.',true)}closeModal('customerAuthModal');updateButtons();showToast('Signed in to your customer account','circle-user-round');const action=pendingAction;pendingAction=null;if(action==='checkout')document.querySelector('#cartCheckoutButton')?.click()}
 async function signUp(form){const client=db();if(!client)return status('Supabase is not connected yet. Add the production Supabase client before accepting customer accounts.',true);const data=Object.fromEntries(new FormData(form));status('Creating your account…');const {data:result,error}=await client.auth.signUp({email:data.email.trim(),password:data.password,options:{data:{full_name:data.fullName.trim(),phone:data.phone.trim(),account_type:'customer'}}});if(error)return status(error.message,true);if(result.session){const registered=await client.rpc('register_customer_profile',{full_name:data.fullName.trim(),phone_number:data.phone.trim(),accepted_terms:true});if(registered.error)return status(registered.error.message,true);user=result.user;await getProfile();updateButtons();closeModal('customerAuthModal');showToast('Customer account created','badge-check')}else status('Check your email to verify the account, then sign in.')}
 async function signOut(){if(db())await db().auth.signOut({scope:'local'});user=null;profile=null;window.ZWCart?.setCustomerIdentity(null);await window.ZWOffline?.setContext('public',{userId:null,email:null,shopId:null,force:true});updateButtons();closeModal('customerOrdersModal');showToast('Signed out. Offline actions remain locked to this account.','log-out')}
 async function resetPassword(){const email=el('customerSignInForm')?.elements.email.value.trim();if(!email)return status('Enter your email address first.',true);if(!db())return status('Supabase is not connected yet.',true);const {error}=await db().auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}${location.pathname}`});status(error?error.message:'Password reset email sent.',!!error)}
 document.addEventListener('submit',event=>{if(!['cartCheckoutForm','customerPaymentForm','orderLookupForm','deliveryRequestForm'].includes(event.target.id))return;if(user&&profile?.status==='active')return;event.preventDefault();event.stopImmediatePropagation();openAuth(event.target.id==='orderLookupForm'?'Sign in to view this private order.':'Sign in before sending an order, payment proof or delivery request.')},true);
 document.addEventListener('click',event=>{const privateAction=event.target.closest('[data-accept-bid],[data-decline-bid],[data-confirm-delivery-received],#trackOrderButton');if(!privateAction)return;if(user&&profile?.status==='active'){if(privateAction.id==='trackOrderButton'){event.preventDefault();event.stopImmediatePropagation();showOrders()}return}event.preventDefault();event.stopImmediatePropagation();openAuth(privateAction.id==='trackOrderButton'?'Sign in to view your private order history.':'Sign in to manage courier offers or confirm a delivery.')},true);
 document.addEventListener('DOMContentLoaded',async()=>{await refresh();db()?.auth.onAuthStateChange(()=>setTimeout(refresh,0));el('customerAccountButton')?.addEventListener('click',()=>user?showOrders():openAuth());el('mobileCustomerAccount')?.addEventListener('click',()=>user?showOrders():openAuth());el('trackOrderButton')?.addEventListener('click',event=>{event.stopImmediatePropagation();showOrders()},{capture:true});document.querySelectorAll('[data-customer-auth-tab]').forEach(button=>button.addEventListener('click',()=>tab(button.dataset.customerAuthTab)));el('customerSignInForm')?.addEventListener('submit',event=>{event.preventDefault();signIn(event.currentTarget)});el('customerSignUpForm')?.addEventListener('submit',event=>{event.preventDefault();signUp(event.currentTarget)});document.querySelector('[data-customer-reset]')?.addEventListener('click',resetPassword);document.querySelector('[data-customer-signout]')?.addEventListener('click',signOut);document.addEventListener('click',event=>{const button=event.target.closest('[data-open-customer-order]');if(!button)return;closeModal('customerOrdersModal');const form=el('orderLookupForm');form.orderId.value=button.dataset.openCustomerOrder;form.token.value=button.dataset.orderToken;form.requestSubmit()})});
 window.ZWCustomer={requireAccount,open:openAuth,showOrders,current:()=>({user,profile}),refresh};
})();
